'use client'

import * as React from 'react'

import { useStrings, type StringsOverrides } from './strings'
import { trapFocus } from './trap'
import { ChevronGlyph, CommentGlyph, CrossGlyph, HeartGlyph, IDENTITY_GLYPH, PinGlyph } from './glyphs'
import { symbolFor } from './identity'

// The component brings its own styles, so an install is never unstyled.
import './comment-tray.css'
import './gamestage-primitives.css'

/**
 * CommentTray: a game's comments, as a bar at the foot of the screen that
 * opens into a sheet. GSUI-414, from the Peacock quiz, Tom 2026-11-19.
 *
 * It is laid out the way Instagram lays out a post's comments, because that is
 * the pattern fans already have in their hands: the newest at the top, a
 * pinned comment above everything, replies folded under their comment, the
 * box at the foot. The things that make it feel right are the point of it:
 *
 * - The sheet is always mounted, so the list is drawn before it opens and
 *   nothing jumps in after the sheet has arrived. It follows a finger, and a
 *   release carries on from where it is at the speed it was moving.
 * - Posting has no confirmation word. The host adds the comment the moment
 *   `onPost` fires, with `status: 'sending'`; it lands at the top, faded, and
 *   turns solid when the host says it is `published`. A failure says so on the
 *   row with Retry, and a comment held for checking says only its author can
 *   see it yet.
 * - Your own comments carry a "You" label, a tint and an accent edge.
 * - Comments arriving while the reader has scrolled away do not move what
 *   they are reading: the list holds its place and a chip counts them, and a
 *   tap on it goes back to the top.
 *
 * It stores no comment, counts no heart and calls no service. Every comment,
 * count and status is the host's, the host flips a heart the moment
 * `onHeart` fires, and every word is a string a producer can change. What the
 * tray keeps is only what belongs to the screen: whether it is open, what is
 * typed, which replies are unfolded and how many arrived out of sight.
 */

export type TrayCommentStatus = 'sending' | 'published' | 'held' | 'failed'

export interface TrayComment {
  /** The host's id, Talkbox's `message_id`. */
  id: string
  /** The name shown on the comment. */
  author: string
  /** A stable id for the commenter, so their symbol is the same everywhere. Defaults to `author`. */
  authorId?: string
  /** The commenter's picture. Without one the tray draws their initial. */
  avatarUrl?: string | null
  /** The words, drawn as text: a comment is never markup. */
  text: string
  /** When it was posted, in epoch milliseconds. */
  at: number
  /** How many hearts it has, the reader's own included. */
  hearts?: number
  /** The reader has hearted it. */
  hearted?: boolean
  /** The reader wrote it. */
  mine?: boolean
  /** Pinned by a producer: drawn above everything else. */
  pinned?: boolean
  /** Where the reader's own comment stands. Absent means published. */
  status?: TrayCommentStatus
  /** How many replies it has, for "View 3 replies" before they are loaded. */
  replyCount?: number
  /** Its replies, oldest first. Undefined until the host has loaded them. */
  replies?: TrayComment[]
}

export interface CommentTrayProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onSubmit'> {
  /** Per-instance words, merged over the provider: every `commentTray.*` key. */
  strings?: StringsOverrides
  /** The comments, top-level only, in any order. Null while loading. */
  comments: TrayComment[] | null
  /**
   * Whether this reader may post. Null while it is not known yet: the box is
   * drawn disabled rather than a sign-in prompt that would flash and vanish.
   */
  canPost: boolean | null
  /** The reader, for the picture beside the box. */
  me?: { name: string; id?: string; avatarUrl?: string | null }
  /** Ask for a display name with the first comment, starting from this. */
  nameRequired?: { suggestion: string }
  /** One-tap emoji above the box. Empty, the default, draws no row. */
  quickEmoji?: string[]
  /** Commenters' pictures in the closed bar. Off by default; drawn only for comments that have one. */
  showFaces?: boolean
  /**
   * A picture or symbol beside each comment and the box. Off by default, so
   * rows start at the name (Tom, 2026-11-19): most fans have no picture, and a
   * column of identical symbols said nothing. Turn it on where they do.
   */
  avatars?: boolean
  /** The longest comment Talkbox takes. */
  maxLength?: number
  /** A line from the host under the box, such as a refused name. */
  note?: string
  /** Open, for a host that controls it. Leave unset and the tray owns it. */
  open?: boolean
  /** Opens on first render, for a tray the tray owns. */
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** A comment was sent. The host adds it with `status: 'sending'` at once. */
  onPost?: (text: string, options: { replyTo?: string; name?: string }) => void
  /** A heart was pressed or taken back. The host flips it at once. */
  onHeart?: (id: string) => void
  onReport?: (id: string) => void
  /** Offered on the reader's own comments only, and only when given. */
  onDelete?: (id: string) => void
  onRetry?: (id: string) => void
  /** A comment's replies were unfolded and `replies` is still undefined. */
  onShowReplies?: (id: string) => void
  /** Offered to a reader who may not post, and only when given. */
  onSignIn?: () => void
  /** The clock the times are read against. */
  now?: () => number
}

const LONG_PRESS_MS = 480
const DOUBLE_TAP_MS = 300
const AT_TOP_PX = 40

// A fan with no picture is drawn as their identity symbol on its hue, the same
// pair `identity` gives the same id everywhere: never a face and never an initial.
function Avatar({ id, url, size }: { id: string; url?: string | null; size?: 'small' }) {
  const symbol = symbolFor(id)
  const Symbol = IDENTITY_GLYPH[symbol.glyph]
  return (
    <span
      className={['gs-comment-tray__avatar', url ? '' : `gs-identity__avatar--hue-${symbol.hue}`].filter(Boolean).join(' ')}
      data-gs-scope="comment-tray"
      data-gs-part="avatar"
      data-gs-avatar={url ? 'image' : 'fallback'}
      data-gs-size={size}
      aria-hidden="true"
    >
      {url ? <img src={url} alt="" loading="lazy" decoding="async" referrerPolicy="no-referrer" /> : <span className={`gs-identity__symbol gs-identity__symbol--${symbol.glyph}`}><Symbol /></span>}
    </span>
  )
}


interface RowContext {
copy: ReturnType<typeof useStrings>
canPost: boolean | null
avatars: boolean
entering: Set<string>
unfolded: Set<string>
when: (at: number) => string
setMenuFor: (comment: TrayComment) => void
setHint: (text: string) => void
startReply: (comment: TrayComment) => void
heart: (comment: TrayComment) => void
toggleReplies: (comment: TrayComment) => void
onHeart?: (id: string) => void
onRetry?: (id: string) => void
}

// One comment. At module level so a re-render of the tray keeps each row, and
// with it the heart's pop and the double tap in progress.
function CommentRow({ comment, parent, ctx }: { comment: TrayComment; parent?: TrayComment; ctx: RowContext }) {
const { copy, canPost, avatars, entering, unfolded, when, setMenuFor, setHint, startReply, heart, toggleReplies, onHeart, onRetry } = ctx
  const status = comment.status ?? 'published'
  const live = status === 'published'
  const press = React.useRef<{ timer: number; x: number; y: number; long: boolean; last: number }>({ timer: 0, x: 0, y: 0, long: false, last: 0 })
  const [burst, setBurst] = React.useState(0)
  const wasHearted = React.useRef(comment.hearted)
  const [pop, setPop] = React.useState(false)
  React.useEffect(() => {
    if (comment.hearted && !wasHearted.current) {
      setPop(true)
      const id = window.setTimeout(() => setPop(false), 450)
      wasHearted.current = comment.hearted
      return () => window.clearTimeout(id)
    }
    wasHearted.current = comment.hearted
  }, [comment.hearted])

  const onPointerDown = (event: React.PointerEvent) => {
    if ((event.target as Element).closest('button')) return
    const p = press.current
    p.long = false
    p.x = event.clientX
    p.y = event.clientY
    window.clearTimeout(p.timer)
    p.timer = window.setTimeout(() => { p.long = true; if (status !== 'sending') setMenuFor(comment) }, LONG_PRESS_MS)
  }
  const cancel = () => window.clearTimeout(press.current.timer)
  const onPointerMove = (event: React.PointerEvent) => {
    if (Math.hypot(event.clientX - press.current.x, event.clientY - press.current.y) > 8) cancel()
  }
  const onPointerUp = (event: React.PointerEvent) => {
    cancel()
    const p = press.current
    if (p.long || (event.target as Element).closest('button')) return
    if (event.timeStamp - p.last < DOUBLE_TAP_MS) {
      p.last = 0
      if (!live) return
      if (!canPost) { setHint(copy['comment-tray.signInToHeart']); return }
      setBurst(n => n + 1)
      if (!comment.hearted) onHeart?.(comment.id)
    } else p.last = event.timeStamp
  }

  const hearts = comment.hearts ?? 0
  const replies = comment.replies ?? []
  const replyCount = Math.max(comment.replyCount ?? 0, replies.length)
  const isOpen = unfolded.has(comment.id)

  return (
    <li
      className="gs-comment-tray__item"
      data-gs-scope="comment-tray"
      data-gs-part="row"
      data-gs-anchor={parent?.id}
      data-gs-item={comment.id}
      data-gs-you={comment.mine ? 'true' : undefined}
      data-gs-pinned={comment.pinned ? 'true' : undefined}
      data-gs-moderation={status === 'failed' ? undefined : status}
      data-gs-error={status === 'failed' ? 'network' : undefined}
      data-gs-revealed={entering.has(comment.id) ? undefined : 'true'}
    >
      <div className="gs-comment-tray__clip">
        <div
          className="gs-comment-tray__row"
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={onPointerUp}
          onPointerLeave={cancel}
          onPointerCancel={cancel}
          onContextMenu={event => { event.preventDefault(); if (status !== 'sending') setMenuFor(comment) }}
        >
          {avatars ? <Avatar id={comment.authorId ?? comment.author} url={comment.avatarUrl} size={parent ? 'small' : undefined} /> : null}
          <div className="gs-comment-tray__body">
            <div className="gs-comment-tray__meta">
              <span className="gs-comment-tray__author" data-gs-scope="comment-tray" data-gs-part="label">{comment.author}</span>
              {comment.mine ? <span className="gs-comment-tray__you" data-gs-scope="comment-tray" data-gs-part="note">{copy['comment-tray.you']}</span> : null}
              {comment.pinned ? (
                <span className="gs-comment-tray__pin" data-gs-scope="comment-tray" data-gs-part="note"><PinGlyph />{copy['comment-tray.pinned']}</span>
              ) : null}
            </div>
            <p className="gs-comment-tray__text" data-gs-scope="comment-tray" data-gs-part="body">{comment.text}</p>
            <div className="gs-comment-tray__actions" data-gs-scope="comment-tray" data-gs-part="actions">
              {live && !comment.pinned ? (
                <span className="gs-comment-tray__time" data-gs-scope="comment-tray" data-gs-part="detail">{when(comment.at)}</span>
              ) : null}
              {status === 'sending' ? <span className="gs-comment-tray__status">{copy['comment-tray.sending']}</span> : null}
              {status === 'held' ? <span className="gs-comment-tray__status">{copy['comment-tray.held']}</span> : null}
              {status === 'failed' ? (
                <>
                  <span className="gs-comment-tray__status" data-gs-error="network">{copy['comment-tray.failed']}</span>
                  {onRetry ? <button type="button" className="gs-comment-tray__link" onClick={() => onRetry(comment.id)}>{copy['comment-tray.retry']}</button> : null}
                </>
              ) : null}
              {live && !comment.pinned ? (
                <button type="button" className="gs-comment-tray__link gs-pressable" data-gs-menu="reply" onClick={() => startReply(parent ?? comment)}>
                  {copy['comment-tray.reply']}
                </button>
              ) : null}
            </div>
          </div>
          {live ? (
            <button
              type="button"
              className="gs-comment-tray__heart"
              data-gs-scope="comment-tray"
              data-gs-part="control"
              data-gs-selected={comment.hearted ? 'true' : undefined}
              data-gs-count={hearts}
              data-gs-motion={pop ? 'pop' : undefined}
              aria-pressed={comment.hearted === true}
              aria-label={copy['comment-tray.heart'](comment.author, hearts)}
              onClick={() => heart(comment)}
            >
              <HeartGlyph filled={comment.hearted === true} className="gs-comment-tray__heart-mark" />
              <span className="gs-comment-tray__heart-count" aria-hidden="true">{hearts > 0 ? hearts : ''}</span>
            </button>
          ) : <span />}
          {burst > 0 ? <span key={burst} className="gs-comment-tray__burst" aria-hidden="true"><HeartGlyph filled /></span> : null}
        </div>
        {!parent && replyCount > 0 ? (
          <div className="gs-comment-tray__thread">
            <button type="button" className="gs-comment-tray__link gs-comment-tray__more" aria-expanded={isOpen} onClick={() => toggleReplies(comment)}>
              <span aria-hidden="true" className="gs-comment-tray__rule" />
              {isOpen ? copy['comment-tray.hideReplies'] : copy['comment-tray.viewReplies'](replyCount)}
            </button>
            {isOpen ? (
              comment.replies === undefined ? (
                <p className="gs-comment-tray__status gs-comment-tray__loading">{copy['comment-tray.loadingReplies']}</p>
              ) : (
                <ol className="gs-comment-tray__replies">
                  {[...replies].sort((a, b) => a.at - b.at).map(reply => <CommentRow key={reply.id} comment={reply} parent={comment} ctx={ctx} />)}
                </ol>
              )
            ) : null}
          </div>
        ) : null}
      </div>
    </li>
  )
}

export function CommentTray(props: CommentTrayProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)
  const {
    comments,
    canPost,
    me,
    nameRequired,
    quickEmoji = [],
    showFaces = false,
    avatars = false,
    maxLength = 500,
    note,
    open: openProp,
    defaultOpen = false,
    onOpenChange,
    onPost,
    onHeart,
    onReport,
    onDelete,
    onRetry,
    onShowReplies,
    onSignIn,
    now = Date.now,
    className,
    ...rest
  } = componentProps

  // ---- open, owned here unless the host owns it ----
  const [openOwn, setOpenOwn] = React.useState(defaultOpen)
  const open = openProp ?? openOwn

  // Mounted while open and while it slides away, and not otherwise, so a
  // closed tray leaves nothing hidden in the page for a keyboard or a screen
  // reader to find. The comments are already in hand from props, so mounting
  // on open draws the whole list before the sheet moves: nothing loads in late.
  const [mounted, setMounted] = React.useState(open)
  const [shown, setShown] = React.useState(open)
  // The sheet has finished arriving, so the bar it covers can leave the page:
  // hidden under the sheet it was text off the screen and a control nobody can reach.
  const [settled, setSettled] = React.useState(open)
  React.useEffect(() => {
    const ms = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--gs-motion-sheet')) || 300
    if (open) {
      const id = window.setTimeout(() => setSettled(true), ms + 50)
      return () => window.clearTimeout(id)
    }
    setSettled(false)
  }, [open])
  React.useEffect(() => {
    if (open) {
      setMounted(true)
      const id = requestAnimationFrame(() => requestAnimationFrame(() => setShown(true)))
      return () => cancelAnimationFrame(id)
    }
    setShown(false)
    const ms = parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--gs-motion-sheet')) || 300
    const id = window.setTimeout(() => setMounted(false), ms + 50)
    return () => window.clearTimeout(id)
  }, [open])
  const setOpen = React.useCallback((next: boolean) => {
    if (openProp === undefined) setOpenOwn(next)
    onOpenChange?.(next)
  }, [openProp, onOpenChange])

  const [draft, setDraft] = React.useState('')
  const [name, setName] = React.useState(nameRequired?.suggestion ?? '')
  const [replyTo, setReplyTo] = React.useState<TrayComment | null>(null)
  const [unfolded, setUnfolded] = React.useState<Set<string>>(() => new Set())
  const [menuFor, setMenuFor] = React.useState<TrayComment | null>(null)
  const [hint, setHint] = React.useState('')
  const [unseen, setUnseen] = React.useState(0)
  const [following, setFollowing] = React.useState(true)
  const [, tick] = React.useState(0)

  React.useEffect(() => { if (nameRequired && !name) setName(nameRequired.suggestion) }, [nameRequired, name])

  const panelRef = React.useRef<HTMLDivElement | null>(null)
  const listRef = React.useRef<HTMLDivElement | null>(null)
  const scrimRef = React.useRef<HTMLDivElement | null>(null)
  const inputRef = React.useRef<HTMLInputElement | null>(null)
  const closeRef = React.useRef<HTMLButtonElement | null>(null)

  // ---- ordering: pinned, then newest first ----
  const top = React.useMemo(() => {
    const all = comments ?? []
    return [...all.filter(c => c.pinned), ...all.filter(c => !c.pinned).sort((a, b) => b.at - a.at)]
  }, [comments])
  // Fans' comments: the producer's pinned prompt is not one.
  const counted = top.filter(c => c.status !== 'failed' && !c.pinned)
  const total = counted.length + counted.reduce((n, c) => n + Math.max(c.replyCount ?? 0, c.replies?.length ?? 0), 0)
  const newest = top.find(c => !c.pinned && (c.status === undefined || c.status === 'published'))

  // ---- arrivals: which ids are new since the last render ----
  const seen = React.useRef<Set<string> | null>(null)
  const [entering, setEntering] = React.useState<Set<string>>(() => new Set())
  const heightBefore = React.useRef(0)
  const followingRef = React.useRef(true)
  followingRef.current = following

  React.useLayoutEffect(() => {
    const ids = new Set<string>()
    for (const c of top) { ids.add(c.id); c.replies?.forEach(r => ids.add(r.id)) }
    const before = seen.current
    seen.current = ids
    if (!before) return
    const fresh = [...ids].filter(id => !before.has(id))
    if (fresh.length === 0) return
    const list = listRef.current
    const allById = new Map<string, TrayComment>()
    for (const c of top) { allById.set(c.id, c); c.replies?.forEach(r => allById.set(r.id, r)) }
    const freshMine = fresh.some(id => allById.get(id)?.mine)
    if (freshMine || followingRef.current || !open) {
      // In view, or the reader's own: open the room for it smoothly, at the top.
      setEntering(new Set(fresh))
      requestAnimationFrame(() => requestAnimationFrame(() => setEntering(new Set())))
      if (freshMine && list) list.scrollTo({ top: 0, behavior: 'smooth' })
    } else if (list) {
      // Out of sight: hold the reader's place and count them on the chip.
      // Done by hand because Safari has no scroll anchoring.
      list.scrollTop += list.scrollHeight - heightBefore.current
      setUnseen(n => n + fresh.filter(id => !allById.get(id)?.mine && top.some(c => c.id === id)).length)
    }
  }, [top, open])
  // The height the list had before the next change lands.
  React.useLayoutEffect(() => { heightBefore.current = listRef.current?.scrollHeight ?? 0 })

  const onScroll = () => {
    const list = listRef.current
    if (!list) return
    const atTop = list.scrollTop < AT_TOP_PX
    if (atTop !== followingRef.current) setFollowing(atTop)
    if (atTop) setUnseen(0)
  }
  const toTop = () => {
    listRef.current?.scrollTo({ top: 0, behavior: 'smooth' })
    setUnseen(0)
  }

  // ---- times stay fresh while open ----
  React.useEffect(() => {
    if (!open) return
    const id = window.setInterval(() => tick(n => n + 1), 30_000)
    return () => window.clearInterval(id)
  }, [open])
  const when = (at: number) => copy['comment-tray.time'](Math.max(0, Math.floor((now() - at) / 60_000)))

  // ---- focus, Escape and the scroll position on open ----
  React.useEffect(() => {
    if (!open || !mounted || !panelRef.current) return
    return trapFocus({
      panel: panelRef.current,
      // The sheet itself, not the close button: a focus ring on Close the
      // moment the sheet opens reads as a fault to a fan on a phone. Tab goes
      // to Close next, so a keyboard loses nothing.
      initial: panelRef.current,
      onEscape: () => { if (menuForRef.current) setMenuFor(null); else setOpen(false) },
    })
  }, [open, mounted, setOpen])
  const menuForRef = React.useRef<TrayComment | null>(null)
  menuForRef.current = menuFor
  React.useEffect(() => {
    if (!open) { setMenuFor(null); return }
    // Drawn before it moved, so placing it at the top costs nothing visible.
    if (listRef.current) listRef.current.scrollTop = 0
    setFollowing(true)
    setUnseen(0)
  }, [open])

  // ---- the hint that floats over the sheet ----
  React.useEffect(() => {
    if (!hint) return
    const id = window.setTimeout(() => setHint(''), 2400)
    return () => window.clearTimeout(id)
  }, [hint])

  // ---- drag to close: the sheet follows the finger ----
  const drag = React.useRef<{ y0: number; h: number; t: number; y: number; v: number; dy: number } | null>(null)
  const paint = (dy: number) => {
    const panel = panelRef.current
    if (!panel) return
    panel.style.transform = `translateY(${dy}px)`
    if (scrimRef.current) scrimRef.current.style.opacity = String(Math.max(0, 1 - dy / panel.offsetHeight))
  }
  const onDragStart = (event: React.PointerEvent) => {
    if ((event.target as Element).closest('button')) return
    const panel = panelRef.current
    if (!panel) return
    drag.current = { y0: event.clientY, h: panel.offsetHeight, t: event.timeStamp, y: event.clientY, v: 0, dy: 0 }
    panel.classList.add('gs-comment-tray__panel--dragging')
    ;(event.currentTarget as Element).setPointerCapture?.(event.pointerId)
  }
  const onDragMove = (event: React.PointerEvent) => {
    const d = drag.current
    if (!d) return
    let dy = event.clientY - d.y0
    if (dy < 0) dy = dy / 4 // a little give past fully open, then resistance
    d.v = (event.clientY - d.y) / Math.max(1, event.timeStamp - d.t)
    d.t = event.timeStamp
    d.y = event.clientY
    d.dy = dy
    paint(dy)
  }
  const onDragEnd = () => {
    const d = drag.current
    const panel = panelRef.current
    if (!d || !panel) return
    drag.current = null
    panel.classList.remove('gs-comment-tray__panel--dragging')
    const far = d.dy > d.h * 0.3 || d.v > 0.6
    panel.style.transform = ''
    if (scrimRef.current) scrimRef.current.style.opacity = ''
    if (far) setOpen(false)
  }

  // ---- posting ----
  const words = draft.trim()
  const tooLong = draft.length > maxLength
  const send = (event?: React.FormEvent) => {
    event?.preventDefault()
    if (!words || tooLong || !onPost) return
    const options: { replyTo?: string; name?: string } = {}
    if (replyTo) {
      options.replyTo = replyTo.id
      setUnfolded(open => new Set(open).add(replyTo.id))
    }
    if (nameRequired) options.name = name.trim()
    onPost(words, options)
    setDraft('')
    setReplyTo(null)
  }
  const startReply = (comment: TrayComment) => {
    if (!canPost) { setHint(copy['comment-tray.signInToComment']); return }
    setReplyTo(comment)
    inputRef.current?.focus()
  }
  const heart = (comment: TrayComment) => {
    if (!canPost) { setHint(copy['comment-tray.signInToHeart']); return }
    onHeart?.(comment.id)
  }
  const toggleReplies = (comment: TrayComment) => {
    const isOpen = unfolded.has(comment.id)
    setUnfolded(current => {
      const next = new Set(current)
      if (isOpen) next.delete(comment.id); else next.add(comment.id)
      return next
    })
    if (!isOpen && comment.replies === undefined) onShowReplies?.(comment.id)
  }

  const ctx: RowContext = { copy, canPost, avatars, entering, unfolded, when, setMenuFor, setHint, startReply, heart, toggleReplies, onHeart, onRetry }

  // ---- the closed bar ----
  const faces = showFaces && avatars
    ? [...new Map(top.filter(c => c.avatarUrl && !c.pinned).map(c => [c.author, c])).values()].slice(0, 3)
    : []

  const loaded = comments !== null

  return (
    <div
      {...rest}
      className={['gs-comment-tray', avatars ? '' : 'gs-comment-tray--no-avatars', className].filter(Boolean).join(' ')}
      data-gs-component="comment-tray"
      data-gs-open={shown ? 'true' : undefined}
      data-gs-empty={loaded && top.length === 0 ? 'true' : undefined}
    >
      {open && settled ? null : (
      <button
        type="button"
        className="gs-comment-tray__bar"
        data-gs-scope="comment-tray"
        data-gs-part="trigger"
        aria-haspopup="dialog"
        aria-expanded={open}
        onClick={() => setOpen(true)}
      >
        <span className="gs-comment-tray__grip" aria-hidden="true" />
        <span className="gs-comment-tray__bar-head">
          <CommentGlyph className="gs-comment-tray__bar-mark" />
          <span className="gs-comment-tray__bar-title" data-gs-scope="comment-tray" data-gs-part="label">{copy['comment-tray.title']}</span>
          {total > 0 ? (
            <span key={total} className="gs-comment-tray__count" data-gs-scope="comment-tray" data-gs-part="value" data-gs-count={total}>{total}</span>
          ) : null}
          {faces.length > 0 ? (
            <span className="gs-comment-tray__faces" aria-hidden="true">
              {faces.map(c => <Avatar key={c.id} id={c.authorId ?? c.author} url={c.avatarUrl} size="small" />)}
            </span>
          ) : null}
        </span>
        {loaded ? (
          <span className="gs-comment-tray__preview" data-gs-scope="comment-tray" data-gs-part="detail">
            <span key={newest?.id ?? 'empty'} className="gs-comment-tray__preview-line">
              {newest ? (<><strong>{newest.mine ? copy['comment-tray.you'] : newest.author}</strong> {newest.text}</>) : copy['comment-tray.emptyLine']}
            </span>
          </span>
        ) : null}
      </button>
      )}

      {mounted ? (<>
      <div
        ref={scrimRef}
        className="gs-comment-tray__scrim"
        data-gs-scope="comment-tray"
        data-gs-part="scrim"
        aria-hidden="true"
        onClick={() => setOpen(false)}
      />

      <div
        ref={panelRef}
        className="gs-comment-tray__panel"
        data-gs-scope="comment-tray"
        data-gs-part="panel"
        data-gs-motion="sheet"
        data-gs-animates="motion"
        role="dialog"
        aria-modal="true"
        aria-label={copy['comment-tray.sheetTitle']}
        tabIndex={-1}
      >
        <div
          className="gs-comment-tray__head"
          onPointerDown={onDragStart}
          onPointerMove={onDragMove}
          onPointerUp={onDragEnd}
          onPointerCancel={onDragEnd}
        >
          <span className="gs-comment-tray__thumb" data-gs-scope="comment-tray" data-gs-part="thumb" aria-hidden="true" />
          <div className="gs-comment-tray__head-row">
            <h2 className="gs-comment-tray__title" data-gs-scope="comment-tray" data-gs-part="label">
              {copy['comment-tray.sheetTitle']}
              {total > 0 ? <span className="gs-comment-tray__title-count">{total}</span> : null}
            </h2>
          </div>
        </div>

        <div
          ref={listRef}
          className="gs-comment-tray__list"
          data-gs-scope="comment-tray"
          data-gs-part="list"
          data-gs-following={following ? 'true' : undefined}
          onScroll={onScroll}
          aria-busy={!loaded}
        >
          {!loaded ? (
            <p className="gs-comment-tray__empty" data-gs-scope="comment-tray" data-gs-part="empty">{copy['comment-tray.loading']}</p>
          ) : top.length === 0 ? (
            <div className="gs-comment-tray__empty" data-gs-scope="comment-tray" data-gs-part="empty">
              <strong>{copy['comment-tray.empty']}</strong>
              <span>{copy['comment-tray.emptyLine']}</span>
            </div>
          ) : (
            <ol className="gs-comment-tray__items">
              {top.map(comment => <CommentRow key={comment.id} comment={comment} ctx={ctx} />)}
            </ol>
          )}
        </div>

        {unseen > 0 && !following ? (
        <button
          type="button"
          className="gs-comment-tray__latest gs-pressable gs-action-type"
          data-gs-scope="comment-tray"
          data-gs-part="control"
          data-gs-count={unseen}
          onClick={toTop}
        >
          <ChevronGlyph direction="up" weight="bold" />
          {copy['comment-tray.newComments'](Math.max(1, unseen))}
        </button>
        ) : null}

        <div className="gs-comment-tray__foot" data-gs-scope="comment-tray" data-gs-part="fields">
          {canPost === false ? (
            onSignIn ? (
              <div className="gs-comment-tray__guest">
                <span>{copy['comment-tray.signInLine']}</span>
                <button type="button" className="gs-comment-tray__sign-in gs-pressable gs-action-type" onClick={onSignIn}>{copy['comment-tray.signIn']}</button>
              </div>
            ) : null
          ) : (
            <form className="gs-comment-tray__form" onSubmit={send}>
              {canPost && quickEmoji.length > 0 ? (
                <div className="gs-comment-tray__quick" data-gs-scope="comment-tray" data-gs-part="actions">
                  {quickEmoji.map(emoji => (
                    <button
                      key={emoji}
                      type="button"
                      className="gs-comment-tray__emoji"
                      aria-label={copy['comment-tray.addEmoji'](emoji)}
                      onClick={() => { setDraft(text => text + emoji); inputRef.current?.focus() }}
                    >
                      {emoji}
                    </button>
                  ))}
                </div>
              ) : null}
              {replyTo ? (
                <div className="gs-comment-tray__replying" data-gs-scope="comment-tray" data-gs-part="note">
                  <span>{copy['comment-tray.replyingTo'](replyTo.author)}</span>
                  <button type="button" className="gs-comment-tray__link gs-pressable" onClick={() => setReplyTo(null)}>{copy['comment-tray.cancel']}</button>
                </div>
              ) : null}
              {canPost && nameRequired ? (
                <label className="gs-comment-tray__name">
                  <span>{copy['comment-tray.name']}</span>
                  <input value={name} onChange={event => setName(event.target.value)} maxLength={30} autoComplete="nickname" />
                </label>
              ) : null}
              <div className="gs-comment-tray__compose">
                {avatars ? <Avatar id={me?.id ?? me?.name ?? ''} url={me?.avatarUrl} /> : null}
                <div className="gs-comment-tray__box">
                  <input
                    ref={inputRef}
                    value={draft}
                    onChange={event => setDraft(event.target.value)}
                    placeholder={replyTo ? copy['comment-tray.replyPlaceholder'](replyTo.author) : copy['comment-tray.placeholder']}
                    aria-label={copy['comment-tray.placeholder']}
                    disabled={!canPost}
                    enterKeyHint="send"
                    autoComplete="off"
                  />
                  <button type="submit" className="gs-comment-tray__post gs-action-type" disabled={!canPost || !words || tooLong}>
                    {copy['comment-tray.post']}
                  </button>
                </div>
              </div>
              {draft.length > maxLength - 50 ? (
                <p className="gs-comment-tray__remaining" data-gs-scope="comment-tray" data-gs-part="value" data-gs-invalid={tooLong ? 'true' : undefined}>
                  {copy['comment-tray.remaining'](maxLength - draft.length)}
                </p>
              ) : null}
              {note ? <p className="gs-comment-tray__note" role="status">{note}</p> : null}
            </form>
          )}
        </div>

        {menuFor ? (
          <>
            <div className="gs-comment-tray__menu-scrim" aria-hidden="true" onClick={() => setMenuFor(null)} />
            <div className="gs-comment-tray__menu" role="menu" data-gs-scope="comment-tray" data-gs-part="menu">
              <p className="gs-comment-tray__menu-quote">{copy['comment-tray.quote'](menuFor.author, menuFor.text)}</p>
              {(menuFor.status ?? 'published') === 'published' && !menuFor.pinned ? (
                <button type="button" className="gs-comment-tray__menu-item gs-action-type" role="menuitem" data-gs-menu="reply" onClick={() => { const c = menuFor; setMenuFor(null); startReply(c) }}>
                  {copy['comment-tray.reply']}
                </button>
              ) : null}
              {menuFor.mine ? (
                onDelete ? (
                  <button type="button" className="gs-comment-tray__menu-item gs-pressable gs-action-type" role="menuitem" data-gs-destructive="true" onClick={() => { const c = menuFor; setMenuFor(null); onDelete(c.id) }}>
                    {copy['comment-tray.delete']}
                  </button>
                ) : null
              ) : onReport ? (
                <button type="button" className="gs-comment-tray__menu-item gs-pressable gs-action-type" role="menuitem" data-gs-menu="report" data-gs-destructive="true" onClick={() => { const c = menuFor; setMenuFor(null); onReport(c.id); setHint(copy['comment-tray.reported']) }}>
                  {copy['comment-tray.report']}
                </button>
              ) : null}
              <button type="button" className="gs-comment-tray__menu-item gs-pressable gs-action-type" role="menuitem" onClick={() => setMenuFor(null)}>{copy['comment-tray.cancel']}</button>
            </div>
          </>
        ) : null}


        {/* Last in the page order, drawn in the top corner: Escape and the
            scrim close it too, and every other control is reached first. */}
        <button
          ref={closeRef}
          type="button"
          className="gs-comment-tray__close"
          data-gs-scope="comment-tray"
          data-gs-part="close"
          aria-label={copy['comment-tray.close']}
          onClick={() => setOpen(false)}
        >
          <CrossGlyph className="gs-comment-tray__close-mark" />
        </button>

        <p className="gs-comment-tray__hint" role="status" data-gs-revealed={hint ? 'true' : undefined}>{hint}</p>
      </div>
      </>) : null}
    </div>
  )
}

/* Comment tray. Every value comes from a token; nothing here is a literal
   colour. A host can retune four things without touching structure:
   --gs-comment-tray-height   how much of its container the open sheet takes
   --gs-comment-tray-heart    the colour of a pressed heart
   --gs-comment-tray-mine     the tint behind the reader's own comments
   --gs-comment-tray-panel-fill  the sheet and bar surface

   The root covers its container, as a sheet does, so a host puts
   `position: relative` on the screen it belongs to. Only the bar, and the
   sheet while open, take a tap: the screen above stays playable. */
.gs-comment-tray {
  --gs-comment-tray-height: 82%;
  --gs-comment-tray-heart: var(--gs-color-negative-solid);
  --gs-comment-tray-mine: color-mix(in srgb, var(--gs-color-interactive-solid) 9%, transparent);
  --gs-comment-tray-panel-fill: var(--gs-color-surface-solid);
  --gs-comment-tray-ease: var(--gs-motion-ease-sheet);
  --gs-comment-tray-open: var(--gs-motion-sheet);

  position: absolute;
  inset: 0;
  z-index: calc(var(--gs-layer-nav, 50) + 1);
  pointer-events: none;
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  line-height: var(--gs-type-body-line-height);
  color: var(--gs-color-ink);
}

/* -- closed: the bar --------------------------------------------------------- */
.gs-comment-tray__bar {
  pointer-events: auto;
  position: absolute;
  inset: auto 0 0 0;
  display: grid;
  gap: var(--gs-space-1);
  text-align: start;
  cursor: pointer;
  border: 0;
  border-radius: var(--gs-radius-xl) var(--gs-radius-xl) 0 0;
  background: var(--gs-comment-tray-panel-fill);
  color: var(--gs-color-ink);
  font: inherit;
  padding: var(--gs-space-2) var(--gs-space-4) calc(var(--gs-space-4) + env(safe-area-inset-bottom, 0px));
  box-shadow: 0 calc(-1 * var(--gs-stroke-hairline)) 0 var(--gs-color-edge), var(--gs-depth-raised);
  transition: transform var(--gs-comment-tray-open) var(--gs-comment-tray-ease);
}
.gs-comment-tray[data-gs-open='true'] .gs-comment-tray__bar { transform: translateY(105%); }
.gs-comment-tray__panel { --gs-comment-tray-close-top: var(--gs-space-1); }
.gs-comment-tray__bar:focus-visible { outline: var(--gs-stroke-focus) solid var(--gs-focus-color, var(--gs-color-ink)); outline-offset: calc(-1 * var(--gs-focus-offset, 3px)); }
.gs-comment-tray__grip,
.gs-comment-tray__thumb {
  justify-self: center;
  display: block;
  width: var(--gs-space-8);
  height: var(--gs-space-1);
  margin: 0 auto;
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-edge-high-solid);
}
.gs-comment-tray__bar-head { display: flex; align-items: center; gap: var(--gs-space-2); min-width: 0; }
.gs-comment-tray__bar-title { font-family: var(--gs-type-label-font-family); font-weight: var(--gs-type-label-font-weight); }
.gs-comment-tray__count {
  min-width: var(--gs-space-6);
  padding: 0 var(--gs-space-2);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-interactive-solid);
  color: var(--gs-color-on-accent-solid);
  font-family: var(--gs-type-label-font-family);
  font-weight: var(--gs-type-label-font-weight);
  font-size: var(--gs-type-caption-font-size);
  text-align: center;
  font-variant-numeric: tabular-nums;
  animation: gs-comment-tray-pop var(--gs-motion-pop) var(--gs-motion-ease-pop);
}
.gs-comment-tray__faces { margin-inline-start: auto; display: flex; }
.gs-comment-tray__faces .gs-comment-tray__avatar { margin-inline-start: calc(-1 * var(--gs-space-2)); box-shadow: 0 0 0 var(--gs-stroke-ui) var(--gs-comment-tray-panel-fill); }
/* One line, and a new newest comment rises into it rather than replacing it. */
.gs-comment-tray__preview { display: block; overflow: hidden; color: var(--gs-color-ink-secondary); }
.gs-comment-tray__preview-line {
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  animation: gs-comment-tray-rise var(--gs-motion-sheet) var(--gs-comment-tray-ease);
}
.gs-comment-tray__preview strong { color: var(--gs-color-ink); font-weight: var(--gs-type-label-font-weight); }

/* -- open: scrim and sheet --------------------------------------------------- */
.gs-comment-tray__scrim {
  position: absolute;
  inset: 0;
  background: var(--gs-color-scrim);
  opacity: 0;
  transition: opacity var(--gs-comment-tray-open) var(--gs-comment-tray-ease);
}
.gs-comment-tray[data-gs-open='true'] .gs-comment-tray__scrim { opacity: 1; pointer-events: auto; }

.gs-comment-tray__panel {
  position: absolute;
  inset: auto 0 0 0;
  height: var(--gs-comment-tray-height);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  background: var(--gs-comment-tray-panel-fill);
  border-radius: var(--gs-radius-xl) var(--gs-radius-xl) 0 0;
  box-shadow: var(--gs-depth-raised);
  outline: none;
  transform: translateY(100%);
  visibility: hidden;
  /* Closing: the move first, then hidden, so it slides away instead of vanishing. */
  transition:
    transform var(--gs-comment-tray-open) var(--gs-comment-tray-ease),
    visibility 0s linear var(--gs-comment-tray-open);
  will-change: transform;
}
.gs-comment-tray[data-gs-open='true'] .gs-comment-tray__panel {
  pointer-events: auto;
  transform: translateY(0);
  visibility: visible;
  transition: transform var(--gs-comment-tray-open) var(--gs-comment-tray-ease), visibility 0s;
}
/* Under a finger the sheet tracks it exactly; the transition comes back on release. */
.gs-comment-tray__panel.gs-comment-tray__panel--dragging { transition: none; }

.gs-comment-tray__head {
  padding-top: var(--gs-space-2);
  border-bottom: var(--gs-stroke-hairline) solid color-mix(in srgb, var(--gs-color-edge) 50%, transparent);
  touch-action: none;
  cursor: grab;
  user-select: none;
}
.gs-comment-tray__head:active { cursor: grabbing; }
.gs-comment-tray__head-row {
  display: grid;
  grid-template-columns: var(--gs-size-touch-min) 1fr var(--gs-size-touch-min);
  align-items: center;
  padding: var(--gs-space-1) var(--gs-space-2) var(--gs-space-2);
}
.gs-comment-tray__title {
  grid-column: 2;
  margin: 0;
  text-align: center;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-label-font-weight);
}
.gs-comment-tray__title-count { margin-inline-start: var(--gs-space-1); color: var(--gs-color-ink-secondary); font-variant-numeric: tabular-nums; }
.gs-comment-tray__close {
  position: absolute;
  top: var(--gs-comment-tray-close-top);
  right: var(--gs-space-2);
  width: var(--gs-size-touch-min);
  height: var(--gs-size-touch-min);
  display: grid;
  place-items: center;
  border: 0;
  border-radius: var(--gs-radius-full);
  background: none;
  color: var(--gs-color-ink-secondary);
  cursor: pointer;
}
.gs-comment-tray__close:focus-visible { outline: var(--gs-stroke-focus) solid var(--gs-focus-color, var(--gs-color-ink)); }

/* -- the list ---------------------------------------------------------------- */
.gs-comment-tray__list {
  position: relative;
  overflow-y: auto;
  overscroll-behavior: contain;
  overflow-anchor: none;
  padding-block: var(--gs-space-1) var(--gs-space-4);
  /* A hairline scrollbar over the edge, as a phone draws one. */
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--gs-color-ink-secondary-solid) 45%, transparent) transparent;
}
.gs-comment-tray__list::-webkit-scrollbar { width: 6px; }
.gs-comment-tray__list::-webkit-scrollbar-track { background: transparent; }
.gs-comment-tray__list::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--gs-color-ink-secondary-solid) 40%, transparent);
  border-radius: var(--gs-radius-full);
}
.gs-comment-tray__items,
.gs-comment-tray__replies { list-style: none; margin: 0; padding: 0; }
.gs-comment-tray__empty {
  display: grid;
  place-content: center;
  gap: var(--gs-space-1);
  height: 100%;
  margin: 0;
  padding: var(--gs-space-6);
  text-align: center;
  color: var(--gs-color-ink-secondary);
}
.gs-comment-tray__empty strong { color: var(--gs-color-ink); font-family: var(--gs-type-label-font-family); font-weight: var(--gs-type-label-font-weight); }

/* A comment opens its own room, so nothing under it jumps. */
.gs-comment-tray__item {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--gs-motion-reorder) var(--gs-comment-tray-ease);
}
.gs-comment-tray__item[data-gs-revealed='true'] { grid-template-rows: 1fr; }
.gs-comment-tray__clip { min-height: 0; overflow: hidden; }
.gs-comment-tray__row {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) var(--gs-size-touch-min);
  gap: 0 var(--gs-space-3);
  padding: var(--gs-space-2) var(--gs-space-2) var(--gs-space-1) var(--gs-space-4);
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
  opacity: 0;
  transform: translateY(var(--gs-space-2));
  transition:
    opacity var(--gs-motion-reorder) var(--gs-comment-tray-ease),
    transform var(--gs-motion-reorder) var(--gs-comment-tray-ease),
    background-color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}
.gs-comment-tray__item[data-gs-revealed='true'] > .gs-comment-tray__clip > .gs-comment-tray__row { opacity: 1; transform: none; }
.gs-comment-tray__item[data-gs-anchor] .gs-comment-tray__row { padding-inline-start: calc(var(--gs-space-4) + var(--gs-size-icon-control) + var(--gs-space-3)); }

/* Yours: a label, a tint and an accent edge. */
.gs-comment-tray__item[data-gs-you='true'] > .gs-comment-tray__clip > .gs-comment-tray__row { background: var(--gs-comment-tray-mine); }
.gs-comment-tray__item[data-gs-you='true'] > .gs-comment-tray__clip > .gs-comment-tray__row::before {
  content: '';
  position: absolute;
  inset: var(--gs-space-2) auto var(--gs-space-2) 0;
  width: var(--gs-stroke-selected);
  border-radius: 0 var(--gs-radius-sm) var(--gs-radius-sm) 0;
  background: var(--gs-color-interactive-solid);
}
/* Pinned is said by its label, as Instagram does. A rule under it drew a dark
   line straight across the row below, right over that row's heart. */
/* Before the room has it: faded, so it reads as on its way. */
.gs-comment-tray__item[data-gs-moderation='sending'] .gs-comment-tray__text,
.gs-comment-tray__item[data-gs-moderation='sending'] .gs-comment-tray__avatar { opacity: 0.55; }

.gs-comment-tray__avatar {
  flex: none;
  width: calc(var(--gs-size-touch-min) * 0.75);
  height: calc(var(--gs-size-touch-min) * 0.75);
  border-radius: var(--gs-radius-full);
  display: grid;
  place-items: center;
  overflow: hidden;
  color: var(--gs-color-ink);
  font-family: var(--gs-type-label-font-family);
  font-weight: var(--gs-type-label-font-weight);
  font-size: var(--gs-type-caption-font-size);
}
.gs-comment-tray__avatar[data-gs-size='small'] { width: var(--gs-size-icon-control); height: var(--gs-size-icon-control); }
.gs-comment-tray__avatar img { width: 100%; height: 100%; object-fit: cover; }
.gs-comment-tray__avatar[data-gs-avatar='image'] { background: var(--gs-color-surface-raised-solid); }

.gs-comment-tray__meta { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--gs-space-1) var(--gs-space-2); font-size: var(--gs-type-caption-font-size); }
.gs-comment-tray__author { font-family: var(--gs-type-label-font-family); font-weight: var(--gs-type-label-font-weight); }
.gs-comment-tray__time { color: var(--gs-color-ink-secondary); font-variant-numeric: tabular-nums; }
.gs-comment-tray__you {
  padding: 0 var(--gs-space-2);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-interactive-solid);
  color: var(--gs-color-on-accent-solid);
  font-family: var(--gs-type-label-font-family);
  font-weight: var(--gs-type-label-font-weight);
  font-size: var(--gs-type-caption-font-size);
  line-height: 1.5;
}
.gs-comment-tray__pin { display: inline-flex; align-items: center; gap: var(--gs-space-1); color: var(--gs-color-ink-secondary); }
.gs-comment-tray__text {
  margin: 0;
  line-height: 1.35;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  transition: opacity var(--gs-motion-reorder) var(--gs-comment-tray-ease);
}
.gs-comment-tray__actions { display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--gs-space-1) var(--gs-space-4); margin-top: 2px; font-size: var(--gs-type-caption-font-size); color: var(--gs-color-ink-secondary); }
.gs-comment-tray__status { color: var(--gs-color-ink-secondary); margin: 0; }
.gs-comment-tray__status[data-gs-error] { color: var(--gs-color-negative-solid); font-weight: var(--gs-type-label-font-weight); }
.gs-comment-tray__link {
  border: 0;
  background: none;
  padding: 0;
  color: inherit;
  font: inherit;
  font-family: var(--gs-type-label-font-family);
  font-weight: var(--gs-type-label-font-weight);
  cursor: pointer;
}
.gs-comment-tray__link:focus-visible { outline: var(--gs-stroke-focus) solid var(--gs-focus-color, var(--gs-color-ink)); border-radius: var(--gs-radius-sm); }
.gs-comment-tray__thread { padding-inline-start: calc(var(--gs-space-4) + calc(var(--gs-size-touch-min) * 0.75) + var(--gs-space-3)); }
.gs-comment-tray__thread .gs-comment-tray__replies { margin-inline-start: calc(-1 * (var(--gs-space-4) + calc(var(--gs-size-touch-min) * 0.75) + var(--gs-space-3))); }
.gs-comment-tray__more { display: inline-flex; align-items: center; gap: var(--gs-space-2); color: var(--gs-color-ink-secondary); font-size: var(--gs-type-caption-font-size); }
.gs-comment-tray__rule { display: inline-block; width: var(--gs-space-6); height: var(--gs-stroke-hairline); background: var(--gs-color-edge-high-solid); }
.gs-comment-tray__loading { font-size: var(--gs-type-caption-font-size); padding-block: var(--gs-space-1); }

/* -- hearts ------------------------------------------------------------------ */
.gs-comment-tray__heart {
  align-self: start;
  display: grid;
  justify-items: center;
  gap: 1px;
  padding: var(--gs-space-1) 0;
  border: 0;
  background: none;
  cursor: pointer;
  color: var(--gs-color-ink-secondary);
  font-family: var(--gs-type-label-font-family);
  font-weight: var(--gs-type-label-font-weight);
  font-size: var(--gs-type-caption-font-size);
  font-variant-numeric: tabular-nums;
}
.gs-comment-tray__heart-mark { width: var(--gs-size-icon-control); height: var(--gs-size-icon-control); stroke-width: 1.4; }
.gs-comment-tray__bar-mark,
.gs-comment-tray__close-mark { width: var(--gs-size-icon-control); height: var(--gs-size-icon-control); }
.gs-comment-tray__heart[data-gs-selected='true'] .gs-comment-tray__heart-mark { color: var(--gs-comment-tray-heart); }
.gs-comment-tray__heart[data-gs-motion='pop'] .gs-comment-tray__heart-mark { animation: gs-comment-tray-pop var(--gs-motion-pop) var(--gs-motion-ease-pop); }
.gs-comment-tray__heart:focus-visible { outline: var(--gs-stroke-focus) solid var(--gs-focus-color, var(--gs-color-ink)); border-radius: var(--gs-radius-sm); }
.gs-comment-tray__heart-count { min-height: 1.2em; }
.gs-comment-tray__burst {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--gs-space-12);
  height: var(--gs-space-12);
  margin: calc(-0.5 * var(--gs-space-12)) 0 0 calc(-0.5 * var(--gs-space-12));
  color: var(--gs-comment-tray-heart);
  pointer-events: none;
  animation: gs-comment-tray-burst 700ms var(--gs-motion-ease-pop) forwards;
}
.gs-comment-tray__burst svg { width: 100%; height: 100%; }

/* -- the new-comments chip: floats over the list and moves nothing ------------ */
.gs-comment-tray__latest {
  position: absolute;
  left: 50%;
  top: calc(var(--gs-space-12) + var(--gs-space-6));
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-1);
  padding: var(--gs-space-2) var(--gs-space-4);
  border: 0;
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-interactive-solid);
  color: var(--gs-color-on-accent-solid);
  font-family: var(--gs-type-label-font-family);
  font-weight: var(--gs-type-label-font-weight);
  font-size: var(--gs-type-caption-font-size);
  box-shadow: var(--gs-depth-raised);
  cursor: pointer;
  transform: translate(-50%, 0);
  animation: gs-comment-tray-drop var(--gs-motion-sheet) var(--gs-comment-tray-ease);
}
.gs-comment-tray__latest:focus-visible { outline: var(--gs-stroke-focus) solid var(--gs-focus-color, var(--gs-color-ink)); outline-offset: var(--gs-focus-offset, 3px); }

/* -- the foot ---------------------------------------------------------------- */
.gs-comment-tray__foot {
  border-top: var(--gs-stroke-hairline) solid var(--gs-color-edge);
  padding: var(--gs-space-2) var(--gs-space-3) calc(var(--gs-space-3) + env(safe-area-inset-bottom, 0px));
}
.gs-comment-tray__form { display: grid; gap: var(--gs-space-2); }
.gs-comment-tray__quick { display: flex; justify-content: space-between; padding-inline: var(--gs-space-1); }
.gs-comment-tray__quick button {
  border: 0;
  background: none;
  color: var(--gs-color-ink);
  font: inherit;
  font-size: var(--gs-type-title-font-size);
  line-height: 1;
  padding: var(--gs-space-1);
  border-radius: var(--gs-radius-sm);
  cursor: pointer;
  transition: transform var(--gs-motion-press) var(--gs-motion-ease-pop);
}
.gs-comment-tray__quick button:active { transform: scale(1.25); }
/* A heart has no surface to push down, so it squeezes instead of taking the
   press slab, which drew a box and a highlight line behind it. */
.gs-comment-tray__heart:active .gs-comment-tray__heart-mark { transform: scale(0.86); transition: transform var(--gs-motion-press) var(--gs-motion-ease-press); }
.gs-comment-tray__heart,
.gs-comment-tray__link,
.gs-comment-tray__emoji,
.gs-comment-tray__close,
.gs-comment-tray__bar,
.gs-comment-tray__post,
.gs-comment-tray__menu-item { -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
.gs-comment-tray__quick button:focus-visible { outline: var(--gs-stroke-focus) solid var(--gs-focus-color, var(--gs-color-ink)); }
.gs-comment-tray__replying { display: flex; justify-content: space-between; align-items: center; padding-inline: var(--gs-space-2); font-size: var(--gs-type-caption-font-size); color: var(--gs-color-ink-secondary); }
.gs-comment-tray__name { display: grid; gap: var(--gs-space-1); font-size: var(--gs-type-caption-font-size); color: var(--gs-color-ink-secondary); padding-inline: var(--gs-space-2); }
.gs-comment-tray__name input,
.gs-comment-tray__box input {
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  color: var(--gs-color-ink);
  font: inherit;
  /* The body size, which every theme sets at 16px or more, so iOS does not
     zoom the page when the box takes focus. */
  font-size: var(--gs-type-body-font-size);
}
.gs-comment-tray__name input { border-bottom: var(--gs-stroke-hairline) solid var(--gs-color-edge); padding: var(--gs-space-1) 0; }
.gs-comment-tray__compose { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--gs-space-2); align-items: center; }
.gs-comment-tray__box {
  display: flex;
  align-items: center;
  gap: var(--gs-space-1);
  padding: var(--gs-space-1) var(--gs-space-1) var(--gs-space-1) var(--gs-space-4);
  border: var(--gs-stroke-hairline) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-background-solid);
  transition: border-color var(--gs-motion-press);
}
.gs-comment-tray__box:focus-within { border-color: var(--gs-color-ink-secondary-solid); }
.gs-comment-tray__box input { flex: 1; padding: var(--gs-space-2) 0; }
.gs-comment-tray__box input::placeholder { color: var(--gs-color-ink-secondary); }
.gs-comment-tray__post {
  border: 0;
  background: none;
  padding: var(--gs-space-2) var(--gs-space-3);
  border-radius: var(--gs-radius-full);
  color: var(--gs-color-interactive-solid);
  font-family: var(--gs-type-label-font-family);
  font-weight: var(--gs-type-label-font-weight);
  cursor: pointer;
  transition: opacity var(--gs-motion-press);
}
.gs-comment-tray__post:disabled { opacity: 0.35; cursor: default; }
.gs-comment-tray__post:focus-visible { outline: var(--gs-stroke-focus) solid var(--gs-focus-color, var(--gs-color-ink)); }
.gs-comment-tray__remaining { margin: 0; text-align: end; padding-inline-end: var(--gs-space-2); font-size: var(--gs-type-caption-font-size); color: var(--gs-color-ink-secondary); font-variant-numeric: tabular-nums; }
.gs-comment-tray__remaining[data-gs-invalid='true'] { color: var(--gs-color-negative-solid); }
.gs-comment-tray__note { margin: 0; padding-inline: var(--gs-space-2); font-size: var(--gs-type-caption-font-size); color: var(--gs-color-ink-secondary); }
.gs-comment-tray__guest { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: var(--gs-space-3); padding: var(--gs-space-1) var(--gs-space-2); color: var(--gs-color-ink-secondary); }
.gs-comment-tray__sign-in {
  border: 0;
  border-radius: var(--gs-radius-full);
  padding: var(--gs-space-2) var(--gs-space-4);
  min-height: var(--gs-size-touch-min);
  background: var(--gs-color-interactive-solid);
  color: var(--gs-color-on-accent-solid);
  cursor: pointer;
}

/* -- long press menu and the hint: both float, neither moves the list -------- */
.gs-comment-tray__menu-scrim { position: absolute; inset: 0; background: var(--gs-color-scrim); animation: gs-comment-tray-fade var(--gs-motion-reorder) var(--gs-motion-ease-fade); }
.gs-comment-tray__menu {
  position: absolute;
  left: var(--gs-space-3);
  right: var(--gs-space-3);
  bottom: calc(var(--gs-space-3) + env(safe-area-inset-bottom, 0px));
  padding: var(--gs-space-1);
  border-radius: var(--gs-radius-xl);
  background: var(--gs-color-surface-raised-solid);
  box-shadow: var(--gs-depth-raised);
  animation: gs-comment-tray-rise var(--gs-motion-sheet) var(--gs-comment-tray-ease);
}
.gs-comment-tray__menu-quote { margin: var(--gs-space-2) var(--gs-space-3); font-size: var(--gs-type-caption-font-size); color: var(--gs-color-ink-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gs-comment-tray__menu button {
  display: block;
  width: 100%;
  min-height: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-3);
  border: 0;
  border-radius: var(--gs-radius-lg);
  background: none;
  text-align: start;
  color: var(--gs-color-ink);
  font: inherit;
  font-family: var(--gs-type-label-font-family);
  font-weight: var(--gs-type-label-font-weight);
  cursor: pointer;
}
.gs-comment-tray__menu button[data-gs-destructive='true'] { color: var(--gs-color-negative-solid); }
.gs-comment-tray__menu button:hover,
.gs-comment-tray__menu button:focus-visible { background: var(--gs-comment-tray-panel-fill); outline: none; }
.gs-comment-tray__hint {
  position: absolute;
  left: 50%;
  top: var(--gs-space-3);
  margin: 0;
  padding: var(--gs-space-2) var(--gs-space-4);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-ink-solid);
  color: var(--gs-comment-tray-panel-fill);
  font-family: var(--gs-type-label-font-family);
  font-weight: var(--gs-type-label-font-weight);
  font-size: var(--gs-type-caption-font-size);
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transform: translate(-50%, calc(-1 * var(--gs-space-4)));
  transition: transform var(--gs-motion-sheet) var(--gs-comment-tray-ease), opacity var(--gs-motion-reorder);
}
.gs-comment-tray__hint[data-gs-revealed='true'] { opacity: 1; transform: translate(-50%, 0); }

@keyframes gs-comment-tray-pop { 0% { transform: scale(1); } 40% { transform: scale(1.35); } 100% { transform: scale(1); } }
@keyframes gs-comment-tray-rise { from { transform: translateY(100%); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes gs-comment-tray-fade { from { opacity: 0; } }
@keyframes gs-comment-tray-drop { from { opacity: 0; transform: translate(-50%, calc(-1 * var(--gs-space-4))); } }
@keyframes gs-comment-tray-burst {
  0% { transform: scale(0); opacity: 0; }
  25% { transform: scale(1.2); opacity: 1; }
  55% { transform: scale(0.95); opacity: 1; }
  100% { transform: scale(1.1) translateY(-14px); opacity: 0; }
}

/* Reduced motion: things appear and go, nothing travels. */
@media (prefers-reduced-motion: reduce) {
  .gs-comment-tray { --gs-comment-tray-open: 1ms; }
  .gs-comment-tray__item,
  .gs-comment-tray__row,
  .gs-comment-tray__hint { transition-duration: 1ms; }
  .gs-comment-tray__latest,
  .gs-comment-tray__count,
  .gs-comment-tray__preview-line,
  .gs-comment-tray__menu,
  .gs-comment-tray__burst,
  .gs-comment-tray__heart[data-gs-motion='pop'] .gs-comment-tray__heart-mark { animation: none; }
}

/* Avatars off: the rows start at the name, and the box takes the full width. */
.gs-comment-tray--no-avatars .gs-comment-tray__row { grid-template-columns: minmax(0, 1fr) var(--gs-size-touch-min); }
.gs-comment-tray--no-avatars .gs-comment-tray__item[data-gs-anchor] .gs-comment-tray__row { padding-inline-start: calc(var(--gs-space-4) + var(--gs-space-6)); }
.gs-comment-tray--no-avatars .gs-comment-tray__thread { padding-inline-start: var(--gs-space-4); }
.gs-comment-tray--no-avatars .gs-comment-tray__thread .gs-comment-tray__replies { margin-inline-start: calc(-1 * var(--gs-space-4)); }
.gs-comment-tray--no-avatars .gs-comment-tray__compose { grid-template-columns: minmax(0, 1fr); }
